query P45($owner: String!, $name: String!, $pr: Int!) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    pullRequest(number: $pr) {
      number state title headRefName baseRefName createdAt
      author { login __typename ... on Bot { databaseId } }
      authorAssociation
      commits(first: 10) {
        totalCount
        nodes { commit { oid authoredByCommitter author { name user { login } } committer { name user { login } } } }
      }
      timelineItems(first: 20) {
        totalCount
        nodes {
          __typename
          ... on HeadRefForcePushedEvent { actor { login __typename } createdAt }
          ... on PullRequestCommit { commit { oid } }
          ... on LabeledEvent { actor { login __typename } label { name } createdAt }
          ... on ReviewRequestedEvent { actor { login __typename } createdAt }
        }
      }
    }
  }
}
